			/**
			 * 데이터 저장
			 */
			function doSave(){
				var bIsValid = false;
				// 데이터 변경사항이 없을시 "변경된 데이터가 없습니다" 출력
				var bIsMod = util.Grid.isModified(app, "grd2", "MSG"||"SAVE",function(){
					
					//메시지 -> 확인 버튼 클릭 시
					//alert("H");
					procAfterSave();
					return false;
				},function(){
					procAfterSave();
					return false;
				})
				if(bIsMod){
					// 그리드 내 컬럼 유효성 체크
					bIsValid = util.validate(app, "grd2",'modify');
				}else{
					procAfterSave();
					return;
				}
				if(bIsValid){
					// 저장 서브미션 호출
					util.Submit.send(app, "subSave", function(pbSuccess){
						if(pbSuccess){
							if(app.lookup('subSave').getMetadata("msg")!=null && app.lookup('subSave').getMetadata("msg")=="-1"){
								util.Msg.alert(app, "저장을 실패하였습니다.", null, null, "저장 안내");
								procAfterSave();
								return;
							}else{
								procAfterSave();
								doList();
							}
						}
					});
					
				}else{
					procAfterSave();
					return;
				}
				
			}

